-- Product catalogue moves from products.json into D1 (images stay in the repo until R2 uploads are enabled).
CREATE TABLE IF NOT EXISTS products (
  product_id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  price INTEGER NOT NULL CHECK (price > 0),
  image TEXT NOT NULL DEFAULT '',
  tag TEXT NOT NULL,
  extra_tags TEXT NOT NULL DEFAULT '[]',
  pack_size TEXT NOT NULL DEFAULT '',
  flavours TEXT NOT NULL DEFAULT '[]',
  featured INTEGER NOT NULL DEFAULT 0,
  customizable INTEGER NOT NULL DEFAULT 1,
  active INTEGER NOT NULL DEFAULT 1,
  sort_order INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS catalogue_categories (
  name TEXT PRIMARY KEY,
  sort_order INTEGER NOT NULL DEFAULT 0
);

